import pathlib,sys,subprocess,json,time,hashlib,os,shutil,datetime
ROOT=pathlib.Path('/tmp/asc-1576-live-races'); BENCH=pathlib.Path('/tmp/asc-1576-e2e')
sys.path.insert(0,str(BENCH)); from isolation import command
CLI=['/opt/node/bin/node','/distribution/dist/bin/agent-skill-chain.js']
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run_cmd(run,args,name,stdin=None,timeout=60):
 state=run/'driver-state';state.mkdir(exist_ok=True)
 for n in ['.codex','.claude']:(state/n).mkdir(exist_ok=True)
 p=subprocess.run(command(run,state)+args,input=stdin,text=True,capture_output=True,timeout=timeout)
 (run/'logs'/(name+'.stdout')).write_text(p.stdout);(run/'logs'/(name+'.stderr')).write_text(p.stderr)
 if p.returncode:raise RuntimeError(name+' failed, see dedicated log')
 return p.stdout
def prepare(case):
 run=ROOT/case
 if run.exists():raise RuntimeError('Refuse overwrite existing fixture')
 project=run/'project';project.mkdir(parents=True);(run/'logs').mkdir();(project/'.race').mkdir();(project/'.claude').mkdir()
 (run/'distribution.txt').write_text(str(BENCH/'distributions/baseline'))
 (project/'package.json').write_text('{"name":"asc-isolated-live-race","private":true,"type":"module"}\n')
 (project/'sentinel.txt').write_text('dummy content must remain unchanged\n')
 (project/'.gitignore').write_text('.race/\n.agent-skill-chain/runtime/\n')
 settings={'env':{'ASC_USER_SENTINEL':'keep'},'permissions':{'allow':['Read']},'hooks':{'SessionStart':[{'hooks':[{'type':'command','command':'true','timeout':1}]}]}}
 (project/'.claude/settings.local.json').write_text(json.dumps(settings,indent=2)+'\n')
 (run/'user-settings.json').write_text(json.dumps(settings,sort_keys=True))
 subprocess.run(['git','init','-q',str(project)],check=True)
 for name,value in [('user.name','Isolated Race Fixture'),('user.email','isolated-race@example.invalid')]:subprocess.run(['git','-C',str(project),'config',name,value],check=True)
 run_cmd(run,CLI+['install','--root=/project','--apply'],'install')
 stale=project/'.agent-skill-chain/runtime/agent-lifecycle';(stale/'worktree.lock').mkdir(parents=True);(stale/'stale.json').write_text('{invalid abandoned session')
 hook=project/'.agent-skill-chain/hooks/asc-agent-lifecycle.mjs';shutil.copyfile(hook,project/'.race/legacy-hook.mjs')
 (project/'.race/assessment.json').write_text(json.dumps({f'Q-{n:02}':{'answer':'unknown','evidence':'Isolated lifecycle race; full requested; no quick certification.'} for n in range(1,9)}))
 out=json.loads(run_cmd(run,CLI+['issue','create','--root=/project','--title=Isolated lifecycle race','--mode=full','--assessment=/project/.race/assessment.json'],'create'))
 staging=out.get('path') or out.get('staging')
 if not isinstance(staging,str):raise RuntimeError('Read create output to obtain staging path')
 (run/'staging.txt').write_text(staging)
 (project/'.race/barrier.mjs').write_text('''import fs from 'node:fs';
const dir='/project/.race';
fs.writeFileSync(dir+'/ready',JSON.stringify({pid:process.pid,time:new Date().toISOString()}));
const started=Date.now();
while(!fs.existsSync(dir+'/release')) {if(Date.now()-started>90000){console.error('BARRIER_TIMEOUT');process.exit(24);} await new Promise(r=>setTimeout(r,50));}
console.log('BARRIER_RELEASED');
''')
 subprocess.run(['git','-C',str(project),'add','.'],check=True);subprocess.run(['git','-C',str(project),'commit','-qm','isolated initial fixture'],check=True)
 (run/'distribution.txt').write_text(str(BENCH/'distributions/candidate'))
 run_cmd(run,CLI+['workflow','advance','--staging='+staging],'preview-before')
 manifest={'dummySentinel':digest(project/'sentinel.txt'),'settings':settings,'stale':digest(stale/'stale.json'),'head':subprocess.check_output(['git','-C',str(project),'rev-parse','HEAD'],text=True).strip()}
 (run/'before.json').write_text(json.dumps(manifest,indent=2))
 prompt=f'''This is a bounded isolated lifecycle concurrency verification, not an implementation task. Existing ASC stages must not be advanced or edited. Run exactly this Bash command first: node /project/.race/barrier.mjs . Do not create ready/release markers yourself, and do not bypass or replace that script. It will be released by an independent driver after an ASC {case} operation. After BARRIER_RELEASED, read /project/sentinel.txt, then run node /distribution/dist/bin/agent-skill-chain.js workflow advance --staging={staging} . Do not apply or write anything else. Return compact JSON with barrierReleased, sentinelText, previewSucceeded, targetStep, and any errors. The tested deletion may remove ASC runtime assets, so an explicit preview error after delete must be reported as an error, never hidden. Do not try repair/install or send messages. Finish this same context after reporting.'''
 (run/'prompt.txt').write_text(prompt)
 print(str(run))
def execute(case):
 run=ROOT/case;project=run/'project';stale=project/'.agent-skill-chain/runtime/agent-lifecycle/stale.json'
 before=json.loads((run/'before.json').read_text());outer=ROOT/'outside-sentinel.txt';outerHash=digest(outer)
 # The copied retired hook must terminate without trusting malformed state/input.
 old=json.loads(run_cmd(run,['node','/project/.race/legacy-hook.mjs'],'old-hook-invalid',stdin='{not JSON',timeout=3));assert old=={}
 state=run/'driver-state'
 stalled=subprocess.Popen(command(run,state)+['node','/project/.race/legacy-hook.mjs'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 try:
  stalled.wait(timeout=.3); host_timeout=False
 except subprocess.TimeoutExpired:
  stalled.kill();stalled.wait();host_timeout=True
 finally:
  if stalled.stdin:stalled.stdin.close()
  if stalled.stdout:stalled.stdout.close()
  if stalled.stderr:stalled.stderr.close()
 p=subprocess.Popen([sys.executable,str(BENCH/'worker.py'),str(run),'codex','race',str(run/'prompt.txt')],stdout=open(run/'logs/driver-worker.log','w'),stderr=open(run/'logs/driver-worker.stderr','w'))
 started=time.monotonic();ready=project/'.race/ready';result={'case':case,'provider':'codex','isolation':'OS filesystem/PID/mount isolation, credentials read-only, host HOME inaccessible, network shared only for provider API','fixture':str(run),'readyObserved':False,'operation':None,'workerCompleted':False,'hostTimeoutCanceledStalledHook':host_timeout}
 try:
  while not ready.exists():
   if p.poll() is not None:raise RuntimeError('Worker exited before real barrier readiness')
   if time.monotonic()-started>180:raise RuntimeError('Worker did not reach barrier within 180 seconds')
   time.sleep(.1)
  result['readyObserved']=True;result['ready']=json.loads(ready.read_text());result['operationStartedAt']=datetime.datetime.now(datetime.timezone.utc).isoformat()
  op=json.loads(run_cmd(run,CLI+[case,'--root=/project','--apply'],'concurrent-'+case))
  result['operation']={'exitCode':0,'finishedAt':datetime.datetime.now(datetime.timezone.utc).isoformat()}
  result['workerAliveDuringOperation']=p.poll() is None
  (project/'.race/release').write_text('driver completed isolated lifecycle operation\n')
  p.wait(timeout=180)
  result['workerCompleted']=p.returncode==0;result['measurement']=json.loads((run/'logs/race.measurement.json').read_text())
  settings=json.loads((project/'.claude/settings.local.json').read_text())
  for key,value in before['settings'].items():
   if key=='hooks':
    for event,groups in value.items():
     assert all(group in settings.get('hooks',{}).get(event,[]) for group in groups)
   else:assert settings[key]==value
  result['userSettingsPreserved']=True
  result['dummySentinelPreserved']=digest(project/'sentinel.txt')==before['dummySentinel']
  result['externalSentinelPreserved']=digest(outer)==outerHash
  result['staleStatePreserved']=stale.exists() and digest(stale)==before['stale']
  result['headPreserved']=subprocess.check_output(['git','-C',str(project),'rev-parse','HEAD'],text=True).strip()==before['head']
  old=json.loads(run_cmd(run,['node','/project/.race/legacy-hook.mjs'],'old-hook-after',stdin='{"hook_event_name":"PreToolUse","tool_name":"Write"}',timeout=3));assert old=={}
  result['oldHookSafeAfter']=True
  result['status']='observed-needs-transcript-review'
 except Exception as e:
  result['status']='failed';result['error']=str(e)
  (project/'.race/release').write_text('driver aborted\n')
  if p.poll() is None:p.terminate()
 finally:
  result['wallSeconds']=time.monotonic()-started;(run/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
if __name__=='__main__':
 ROOT.mkdir(exist_ok=True)
 if not (ROOT/'outside-sentinel.txt').exists():(ROOT/'outside-sentinel.txt').write_text('outside dummy immutable sentinel\n')
 {'prepare':prepare,'execute':execute}[sys.argv[1]](sys.argv[2])

