import pathlib,json,hashlib,subprocess
ROOT=pathlib.Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def verify_distribution(run):
 d=pathlib.Path((run/'distribution.txt').read_text().strip()).resolve()
 assert d.parent==(ROOT/'distributions').resolve()
 expected=json.loads((ROOT/'distributions-inventory.json').read_text())[d.name]
 actual={}
 for p in sorted(d.rglob('*')):
  if p.is_symlink():
   assert not p.readlink().is_absolute() and p.resolve().is_relative_to(d)
   actual[str(p.relative_to(d))]={'symlink':str(p.readlink())}
  elif p.is_file():actual[str(p.relative_to(d))]={'sha256':sha(p),'bytes':p.stat().st_size}
 assert actual==expected,'Distribution inventory mismatch'
 return hashlib.sha256(json.dumps(actual,sort_keys=True).encode()).hexdigest()
def preflight(run):
 inventory=verify_distribution(run);project=run/'project';before=json.loads((run/'before.json').read_text())
 assert sha(project/'sentinel.txt')==before['dummySentinel']
 assert sha(project/'.agent-skill-chain/runtime/agent-lifecycle/stale.json')==before['stale']
